const D = { energy:.45, density:.5, size:.5, hue:35, depth:.6, drift:.5, x:.5, y:.5, scale:1, speed:1, style:'warm', seed:0, alpha:75 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,dc=drawingContext;
function hueFor(i){ if(sty==='rainbow') return (i*47+t*8)%360; if(sty==='cool') return 180+fr(i)*80; if(sty==='mono') return P.hue; if(sty==='festive') return [0,45,140,210,300][i%5]; return 20+fr(i)*45; } // warm
const sat=sty==='mono'?15:70;
const N=Math.floor(10+P.density*46);
dc.save();
blendMode(sty==='mono'?BLEND:ADD);
for(let i=0;i<N;i++){
  const dp = fr(i);                    // depth 0(far)..1(near)
  const spd = (0.02+dp*0.10)*(0.4+en)*P.speed*(0.4+P.drift);
  const px = ((fr(i+7) + t*spd*(fr(i+3)>0.5?1:-1))%1)*W;
  const py = ((fr(i+11) + t*spd*0.6)%1)*H;
  const wob = Math.sin(t*(0.5+fr(i)*1.5)+i)*10*dp;
  const r = (6 + dp*dp*90*(0.4+P.size))*P.scale;
  const foc = dp<0.25;                 // a few in-focus (bright, small, ringed)
  const h=hueFor(i), br= foc? 100 : (55+dp*40);
  const a = (foc? 70 : 26+dp*30) * (P.alpha/100) * (0.7+0.3*Math.sin(t*0.7+i));
  if(foc){ dc.shadowBlur=14; dc.shadowColor=color(h,sat,100).toString(); }
  fill(color(h,sat*(foc?1:0.8),br, a));
  circle(px+wob, py+wob*0.6, r);
  if(!foc){ // soft ring edge (bokeh look)
    noFill(); stroke(color(h,sat,br, a*0.5)); strokeWeight(r*0.10); circle(px+wob,py+wob*0.6, r*0.94); noStroke();
  }
  dc.shadowBlur=0;
}
dc.restore();
blendMode(BLEND);
